    static async Task<JsonElement> Json(HttpResponseMessage r)=>JsonDocument.Parse(await r.Content.ReadAsStringAsync()).RootElement.Clone();
    static async Task<string> Token(HttpClient c){var html=await c.GetStringAsync("/index.html");return JsonDocument.Parse(Regex.Match(html,"<script id=\"kicks-auth-state\" type=\"application/json\">(.*?)</script>",RegexOptions.Singleline).Groups[1].Value).RootElement.GetProperty("token").GetString()!;}
    static async Task<HttpResponseMessage> Post(HttpClient c,string url,Dictionary<string,string>? values=null,bool csrf=true){values??=[];if(csrf)values["__RequestVerificationToken"]=await Token(c);return await c.PostAsync(url,new FormUrlEncodedContent(values));}
    static async Task Expect(Task<HttpResponseMessage> task,HttpStatusCode code,string name){using var r=await task;Check(r.StatusCode==code,name+" ("+(int)r.StatusCode+")");}
    static async Task Login(HttpClient c,string email){await Expect(Post(c,"/Pages/Auth/login.html",new(){{"Email",email},{"Password",Password}}),HttpStatusCode.Redirect,"Identity fixture login");}
    sealed record Data(User Owner,User OtherOwner,User Player,User Second,User Third,User Host,User Target,User Member,int Field,int OtherField,int HostTeam,int TargetTeam);
    static async Task<User> User(UserManager<User> users,string marker,string suffix,string role){var u=new User{Email=marker+"-"+suffix+"@example.test",UserName=marker+"-"+suffix+"@example.test",FullName="Phase5 temporary "+suffix,Status="Active",LockoutEnabled=true};if(!(await users.CreateAsync(u,Password)).Succeeded||!(await users.AddToRoleAsync(u,role)).Succeeded)throw new Exception("Fixture setup failed");return u;}
    static async Task<Data> Setup(KicksDbContext db,UserManager<User> users,string marker)
    {
        var owner=await User(users,marker,"owner","owner");var other=await User(users,marker,"other-owner","owner");var player=await User(users,marker,"player","player");var second=await User(users,marker,"second","player");var third=await User(users,marker,"third","player");var host=await User(users,marker,"host","player");var target=await User(users,marker,"target","player");var member=await User(users,marker,"member","player");
        var field=new Field{OwnerId=owner.Id,Name=marker+" pitch",City="Amman",Area="Isolated",Description="Temporary phase5 fixture",HourlyPrice=20};var otherField=new Field{OwnerId=other.Id,Name=marker+" other",City="Amman",Area="Isolated",Description="Temporary fixture",HourlyPrice=25};db.Fields.AddRange(field,otherField);
        var a=new Team{CaptainId=host.Id,Name="Host "+marker[^10..],City="Amman",Area="Test",Bio="Fixture",Initials="HST"};var b=new Team{CaptainId=target.Id,Name="Target "+marker[^10..],City="Amman",Area="Test",Bio="Fixture",Initials="TGT"};db.Teams.AddRange(a,b);await db.SaveChangesAsync();db.TeamMembers.AddRange(new TeamMember{TeamId=a.Id,UserId=host.Id},new TeamMember{TeamId=b.Id,UserId=target.Id},new TeamMember{TeamId=b.Id,UserId=member.Id});await db.SaveChangesAsync();return new(owner,other,player,second,third,host,target,member,field.Id,otherField.Id,a.Id,b.Id);
    }
    public static async Task Fixture(string marker,bool cleanup){if(!Regex.IsMatch(marker,"^phase5-browser-[a-f0-9]{32}$"))throw new Exception("Bad marker");using var factory=new AuthFactory();using var scope=factory.Services.CreateScope();var db=scope.ServiceProvider.GetRequiredService<KicksDbContext>();if(cleanup){await Cleanup(db,marker);return;}var d=await Setup(db,scope.ServiceProvider.GetRequiredService<UserManager<User>>(),marker);Console.WriteLine(JsonSerializer.Serialize(new{fieldId=d.Field,otherFieldId=d.OtherField,hostTeamId=d.HostTeam,targetTeamId=d.TargetTeam}));}
    static Dictionary<string,string> Slot(int field,DateOnly day,int hour=17,int duration=60)=>new(){{"FieldId",field.ToString()},{"Date",day.ToString("yyyy-MM-dd")},{"Hour",hour.ToString()},{"DurationMinutes",duration.ToString()},{"Capacity","2"},{"Title","SQL Open Game"}};
    static Dictionary<string,string> Proposal(Data d,DateOnly day,int hour=17,int duration=60,bool field=true){var input=Slot(d.Field,day,hour,duration);input["TargetTeamId"]=d.TargetTeam.ToString();input["Note"]="Unpaid SQL proposal";if(!field)input.Remove("FieldId");return input;}
    static async Task<string> GameQuote(HttpClient c,Dictionary<string,string> input){using var r=await Post(c,"/games/quote",input);if(!r.IsSuccessStatusCode)throw new Exception("Game quote failed "+await r.Content.ReadAsStringAsync());return(await Json(r)).GetProperty("token").GetString()!;}
    static async Task<int> Game(HttpClient c,Dictionary<string,string> input){var q=await GameQuote(c,input);using var r=await Post(c,"/games",new(){{"Token",q}});if(!r.IsSuccessStatusCode)throw new Exception("Game failed");return(await Json(r)).GetProperty("id").GetInt32();}
    static async Task<int> Challenge(HttpClient c,Dictionary<string,string> input){using var r=await Post(c,"/challenges",input);if(!r.IsSuccessStatusCode)throw new Exception("Challenge failed "+await r.Content.ReadAsStringAsync());return(await Json(r)).GetProperty("id").GetInt32();}
    static async Task<JsonElement> Detail(HttpClient c,string kind,int id)=>await Json(await c.GetAsync("/api/"+kind+"/"+id));
    static async Task<string> BookingQuote(HttpClient c,int field,DateOnly day,int hour=17,int duration=60){using var r=await c.GetAsync($"/bookings/quote?FieldId={field}&Date={day:yyyy-MM-dd}&Hour={hour}&DurationMinutes={duration}");if(!r.IsSuccessStatusCode)throw new Exception("Booking quote failed");return(await Json(r)).GetProperty("quoteToken").GetString()!;}
