            }
            var ownerRaceDay=day.AddDays(15);var oq=await GameQuote(owner,Slot(d.Field,ownerRaceDay));race=await Race((owner,"/games",new(){{"Token",oq}}),(otherOwner,"/games/quote",Slot(d.Field,ownerRaceDay)));Check(race.Count(r=>r.IsSuccessStatusCode)==1&&race.Count(r=>r.StatusCode==HttpStatusCode.NotFound)==1,"two-owner scheduling attempt authorizes only actual field owner");foreach(var r in race)r.Dispose();
            var lifecycle=await Game(owner,Slot(d.Field,day.AddDays(16)));await Expect(Post(player,$"/games/{lifecycle}/join"),HttpStatusCode.Created,"participation race fixture joins");await Expect(Post(second,$"/games/{lifecycle}/join"),HttpStatusCode.Created,"participation race fixture fills");race=await Race((player,$"/games/{lifecycle}/leave",new()),(third,$"/games/{lifecycle}/join",new()));Check(race[0].IsSuccessStatusCode&&await db.GameParticipants.CountAsync(p=>p.GameId==lifecycle&&p.Status=="Joined")<=2,"leave racing join preserves capacity");foreach(var r in race)r.Dispose();dto=await Detail(owner,"games",lifecycle);race=await Race((owner,$"/games/{lifecycle}/cancel",new(){{"Version",dto.GetProperty("version").GetString()!}}),(player,$"/games/{lifecycle}/join",new()));Check(race[0].IsSuccessStatusCode&&await db.OpenGames.AnyAsync(g=>g.Id==lifecycle&&g.Status=="Cancelled")&&await db.GameParticipants.CountAsync(p=>p.GameId==lifecycle&&p.Status=="Joined")<=2,"cancellation racing participation keeps historical joins and valid capacity");foreach(var r in race)r.Dispose();
            var transferChallenge=await Challenge(host,Proposal(d,day.AddDays(17),17,60,false));c=await Detail(target,"challenges",transferChallenge);cv=c.GetProperty("version").GetString()!;var team=await Json(await target.GetAsync("/api/teams/"+d.TargetTeam));race=await Race((target,$"/challenges/{transferChallenge}/accept",new(){{"Version",cv}}),(target,$"/teams/{d.TargetTeam}/transfer/{d.Member.Id}",new(){{"Version",team.GetProperty("version").GetString()!}}));Check(race[1].IsSuccessStatusCode&&(race[0].IsSuccessStatusCode||race[0].StatusCode==HttpStatusCode.Forbidden),"captain transfer racing response observes serialized current authority");foreach(var r in race)r.Dispose();
            var next=await Challenge(host,Proposal(d,day.AddDays(18),17,60,false));c=await Detail(member,"challenges",next);await Expect(Post(target,$"/challenges/{next}/accept",new(){{"Version",c.GetProperty("version").GetString()!}}),HttpStatusCode.Forbidden,"former target captain immediately loses response authority");await Expect(Post(member,$"/challenges/{next}/accept",new(){{"Version",c.GetProperty("version").GetString()!}}),HttpStatusCode.OK,"new current captain can accept existing SQL proposal");
            var exp=await Challenge(host,Proposal(d,day.AddDays(19),17,60,false));c=await Detail(member,"challenges",exp);clock.Value=c.GetProperty("startsAt").GetDateTimeOffset();await Expect(Post(member,$"/challenges/{exp}/accept",new(){{"Version",c.GetProperty("version").GetString()!}}),HttpStatusCode.Conflict,"expired proposal cannot be accepted");clock.Value=realTime;
            group="Account enforcement";d.Owner.Status="Inactive";await users.UpdateAsync(d.Owner);using(var denied=await Post(owner,"/games/quote",Slot(d.Field,day.AddDays(22))))Check(!denied.IsSuccessStatusCode,"inactive owner cannot create games");d.Owner.Status="Active";await users.UpdateAsync(d.Owner);
            Check(await db.Challenges.AnyAsync(x=>x.Id==cid)&&await db.OpenGames.AnyAsync(x=>x.Id==id&&x.Status=="Cancelled"),"game/challenge historical records remain intact");
        }finally{group="Fixture preservation";await Cleanup(db,marker);Check(!await db.Users.AnyAsync(u=>u.Email!.StartsWith(marker)),"only isolated phase5 fixtures removed");}
        foreach(var item in groups)Console.WriteLine($"SECTION: {item.Key}: {item.Value}");Console.WriteLine($"Completed {passed} phase5 SQL assertions.");
    }
    static async Task Cleanup(KicksDbContext db,string marker)
    {
        db.ChangeTracker.Clear();var users=await db.Users.Where(u=>u.Email!.StartsWith(marker+"-")).Select(u=>u.Id).ToListAsync();var fields=await db.Fields.Where(f=>users.Contains(f.OwnerId)).Select(f=>f.Id).ToListAsync();var teams=await db.Teams.Where(t=>users.Contains(t.CaptainId)).Select(t=>t.Id).ToListAsync();var challenges=await db.Challenges.Where(c=>teams.Contains(c.HostTeamId)&&users.Contains(c.PostedBy)).Select(c=>c.Id).ToListAsync();var games=await db.OpenGames.Where(g=>fields.Contains(g.FieldId)&&users.Contains(g.OrganizerId)).Select(g=>g.Id).ToListAsync();var bookings=await db.Bookings.Where(b=>fields.Contains(b.FieldId)&&users.Contains(b.UserId)).Select(b=>b.Id).ToListAsync();await using var tx=await db.Database.BeginTransactionAsync();await db.BookingTeams.Where(bt=>bookings.Contains(bt.BookingId)&&teams.Contains(bt.TeamId)).ExecuteDeleteAsync();await db.Bookings.Where(b=>bookings.Contains(b.Id)).ExecuteDeleteAsync();await db.ChallengeRequests.Where(r=>challenges.Contains(r.ChallengeId)&&teams.Contains(r.TeamId)).ExecuteDeleteAsync();await db.Challenges.Where(c=>challenges.Contains(c.Id)).ExecuteDeleteAsync();await db.GameParticipants.Where(p=>games.Contains(p.GameId)&&users.Contains(p.UserId)).ExecuteDeleteAsync();await db.OpenGames.Where(g=>games.Contains(g.Id)).ExecuteDeleteAsync();await db.TeamRequests.Where(r=>teams.Contains(r.TeamId)&&users.Contains(r.UserId)).ExecuteDeleteAsync();await db.TeamMembers.Where(m=>users.Contains(m.UserId)&&teams.Contains(m.TeamId)).ExecuteDeleteAsync();await db.TeamRecruitingPositions.Where(p=>teams.Contains(p.TeamId)).ExecuteDeleteAsync();await db.Teams.Where(t=>teams.Contains(t.Id)).ExecuteDeleteAsync();await db.FieldImages.Where(i=>fields.Contains(i.FieldId)).ExecuteDeleteAsync();await db.FieldAmenities.Where(i=>fields.Contains(i.FieldId)).ExecuteDeleteAsync();await db.Fields.Where(f=>fields.Contains(f.Id)).ExecuteDeleteAsync();await db.UserRoles.Where(u=>users.Contains(u.UserId)).ExecuteDeleteAsync();await db.UserClaims.Where(u=>users.Contains(u.UserId)).ExecuteDeleteAsync();await db.UserLogins.Where(u=>users.Contains(u.UserId)).ExecuteDeleteAsync();await db.UserTokens.Where(u=>users.Contains(u.UserId)).ExecuteDeleteAsync();await db.Users.Where(u=>users.Contains(u.Id)).ExecuteDeleteAsync();await tx.CommitAsync();
    }
